const esc = (value) => String(value ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]);
const password = (name, label, autocomplete) => `<label class="field auth-field">${label}<span class="password-wrap"><input name="${name}" id="auth-${name}" type="password" autocomplete="${autocomplete}" required minlength="${autocomplete === "current-password" ? 1 : 8}" maxlength="128"><button type="button" data-action="show-password" data-target="auth-${name}" aria-label="Show ${label.toLowerCase()}" aria-pressed="false">Show</button></span></label>`;
export function authPage({ mode = "login", configured = false, loading = false, recovery = false, message = "", email = "" } = {}) {
  const titles = { login: "Welcome back", signup: "Join your anime world", forgot: "Forgot your password?", reset: "Choose a new password", verify: "Check your inbox" };
  const descriptions = { login: "Your next episode is waiting. Log in to keep your anime world together.", signup: "Save your favorites and pick up where you left off, on any device.", forgot: "Enter your account email and we’ll send you a reset link.", reset: "Give your account a fresh start with a new password.", verify: "If your signup was accepted, a confirmation link is on its way. Open it to finish creating your account." };
  const blocked = !configured || loading || mode === "reset" && !recovery, formMode = ["login", "signup", "forgot", "reset"].includes(mode);
  return `<header class="topbar"><div class="topbar-inner"><a class="icon-button" href="#home" aria-label="Back to AniVerse">‹</a><h1 class="page-heading">${mode === "signup" ? "Create Account" : mode === "login" ? "Log In" : "Account Access"}</h1></div></header><main class="auth-page"><a class="auth-brand" href="#home" aria-label="AniVerse home"><img src="./assets/733b0.png" alt=""><span>Ani<span>Verse</span></span></a><div class="auth-heading"><span class="eyebrow orange">YOUR ANIME WORLD, ANYTIME.</span><h2>${titles[mode] || titles.login}</h2><p>${descriptions[mode] || descriptions.login}</p></div><section class="auth-card">${!configured ? '<p class="auth-service-note" role="status">Account services aren’t connected yet. You can still browse and watch as a guest.</p>' : loading ? '<p class="auth-service-note" role="status">Connecting to your account…</p>' : ""}${mode === "reset" && configured && !loading && !recovery ? '<p class="auth-service-note">This reset link could not be verified. It may have expired or already been used. Request a new link below.</p><a class="btn secondary full" href="#forgot-password">Send a new reset link</a>' : ""}${formMode ? `<form id="auth-form" data-mode="${mode}" class="stack">${mode === "signup" ? '<label class="field auth-field">Display name<input name="name" autocomplete="nickname" placeholder="What should we call you?" required minlength="2" maxlength="60"></label>' : ""}${mode !== "reset" ? `<label class="field auth-field">Email address<input name="email" type="email" autocomplete="email" placeholder="you@example.com" value="${esc(email)}" required maxlength="254"></label>` : ""}${mode !== "forgot" ? password("password", mode === "reset" ? "New password" : "Password", mode === "login" ? "current-password" : "new-password") : ""}${["signup", "reset"].includes(mode) ? `${password("confirmPassword", "Confirm password", "new-password")}<p class="auth-hint">Use at least 8 characters. Make it something only you know.</p>` : ""}${mode === "login" ? '<a class="auth-forgot" href="#forgot-password">Forgot password?</a>' : ""}<p id="auth-error" class="form-error" role="alert"></p><p id="auth-message" class="auth-message" role="status">${esc(message)}</p><button type="submit" class="btn primary full" ${blocked ? "disabled" : ""}>${{ login: "Log In", signup: "Create Account", forgot: "Send Reset Link", reset: "Update Password" }[mode]}</button></form>` : `<p class="auth-message" role="status">${esc(message)}</p><a class="btn primary full" href="#login">Back to Log In</a>`}${mode === "login" ? '<p class="auth-switch">New to AniVerse? <a href="#signup">Create an account</a></p>' : mode === "signup" ? '<p class="auth-switch">Already have an account? <a href="#login">Log in</a></p>' : mode !== "verify" ? '<p class="auth-switch"><a href="#login">Back to log in</a></p>' : ""}</section><div class="auth-divider"><span></span>OR<span></span></div><a class="btn secondary full" href="#home">Continue as Guest</a><p class="auth-footnote">Keep your watchlist, progress, and notes in one place.<br>Downloaded videos stay on the device where you save them.</p></main>`;
}
